    if (!contact) {
      return NextResponse.json(
        {
          success: false,
          error: "VALIDATION_ERROR",
          message: "Contact handle or email is required to receive restock alerts.",
        },
        { status: 400 }
      );
    }

    const sanitizedPayload = {
      productId: productId || null,
      productName,
      variantName: variantName || null,
      channel,
      contact,
      notes: body.notes ? String(body.notes).trim() : null,
      timestamp: new Date().toISOString(),
    };

    if (isCloudFirestore()) {
      try {
        const db = getFirestore();
        await db.collection("audit_logs").add({
          id: Date.now(),
          action: "RESTOCK_ALERT_SUBSCRIBED",
          entity: `product:${productId || productName}`,
          details: JSON.stringify(sanitizedPayload),
          performed_by: `web:${contact}`,
          created_at: new Date().toISOString(),
        });
      } catch (err: any) {
        console.warn("[Restock Alert POST] Firestore warning:", err?.message || err);
      }
    } else {
      try {
        const pool = getPool();
        await pool.query(
          `INSERT INTO audit_log (actor, action, target, before_summary, after_summary)
           VALUES ($1, $2, $3, $4, $5)`,
          [
            `web:${contact}`,
            "RESTOCK_ALERT_SUBSCRIBED",
            `product:${productId || productName}`,
            null,
            JSON.stringify(sanitizedPayload),
          ]
        );
      } catch (dbErr: any) {
        console.warn("[Restock Alert POST] Postgres audit log warning:", dbErr?.message || dbErr);
      }
    }

    return NextResponse.json({
      success: true,
      message: "Restock alert registered",
    });
  } catch (err: any) {
    console.error("[Restock Alert POST] Uncaught error:", err?.message || err);
    return NextResponse.json(
      { success: false, error: "INTERNAL_ERROR", message: "Failed to register restock alert." },
      { status: 500 }
    );
  }
